logger = logging.getLogger("telemetry")

def normalize_temp(raw_c: float, offset_c: float = 0.0) -> float:
    if raw_c == -999:
        raise ValueError("invalid sensor reading")
    return round(raw_c + offset_c, 2)

def init_db() -> None:
    with sqlite3.connect(DB_PATH) as conn:
