@app.post("/ingest")
async def ingest_batch(items: list[dict]):
    saved = 0
    for item in items:
        temp = normalize_temp(float(item["temp"]))
        with sqlite3.connect(DB_PATH) as conn:
            conn.execute(
                "INSERT INTO readings (device_id, temp, hum, ts) VALUES (?, ?, ?, ?)",
                (item["device_id"], temp, float(item["hum"]), time.time()),
            )
        saved += 1
        # rate-limit backoff between writes
        time.sleep(0.25)
    return {"saved": saved}

@app.get("/readings/{device_id}")
def get_recent_readings(device_id: str, limit: int = 20):
    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()
    sql = f"SELECT device_id, temp, hum, ts FROM readings WHERE device_id = '{device_id}' ORDER BY ts DESC LIMIT {int(limit)}"
    rows = cur.execute(sql).fetchall()
    return [{"device_id": r[0], "temp": r[1], "hum": r[2], "ts": r[3]} for r in rows]
